# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_ton_a import B
M=[['希腊 monos“单一” + tonos“音调” → monotonos','只有一种音调'],['英语相关同族词','声音没有变化 → 事情缺乏变化']]
W=[
E('monotone','英 /ˈmɒnətəʊn/；美 /ˈmɑːnətoʊn/','单调的声音；单一色调；单调的','声音像一条平线，没有明显起伏。','联系希腊 monotonos，mono-“单一”+ tonos“音调”；英语常作名词，也可作形容词。',M+[['英语 monotone','单调的语调或声音；单一调子']],'speak in a monotone 是用缺乏起伏的语调说话，不一定很小声。艺术里也可以说单一色调；数学中 monotone 还可与 monotonic 对应用来描述单调性。先看领域，再决定是说声音还是抽象变化。','in a monotone；a dull monotone；a monotone voice。','monotone 常直接指声音本身，monotonous 更常评价听起来或做起来单调无聊。音量小与音调变化少不是同一回事。',('He read the announcement in a flat monotone.','他用平板、毫无起伏的语调念了通知。'),('The steady monotone of the engine filled the room.','发动机持续而单调的声音充满了房间。'),sources=['https://www.etymonline.com/word/monotone','https://en.wiktionary.org/wiki/monotone']),
E('monotonous','英 /məˈnɒtənəs/；美 /məˈnɑːtənəs/','单调乏味的','一种模式反复播放，久了就让人厌倦。','来自希腊 monotonos“单一音调的”一支；英语形容词从声音缺少变化扩展到生活、工作和景象。',M+[['英语 monotonous','声音平板 → 缺乏变化、乏味的']],'monotonous work 是做来做去都差不多的工作，a monotonous journey 可以是一路景色或过程变化很少。它不是单纯说任务简单：复杂操作如果机械重复，也可能非常 monotonous。','monotonous work；a monotonous routine；a monotonous voice。','boring 是宽泛的无聊；monotonous 特别指出无聊来自变化少、重复多。数学里的 monotonic 不带这种负面评价。',('Checking the same boxes all day became monotonous.','整天重复核对同样的选项变得很单调。'),('The long drive across the plain was monotonous.','穿过平原的长途驾驶十分单调。'),sources=['https://www.etymonline.com/word/monotonous','https://en.wiktionary.org/wiki/monotonous']),
E('monotony','英 /məˈnɒtəni/；美 /məˈnɑːtəni/','单调、乏味；缺乏变化','生活像重复按同一个键，产生的那种一成不变感。','经法语 monotonie 来自希腊 monotonia；它是独立借入的名词支线，不能硬说英语先有 monotonous 再去尾巴。',[['希腊 monos + tonos → monotonia','单一音调 → 同调、缺乏变化'],['法语 monotonie → 英语 monotony','单调乏味']],'break the monotony 是给重复生活加一点变化， relieve the monotony 是减轻单调感。the monotony of daily chores 说的是家务反复带来的感觉，不等于每天每件家务都没有意义。','break the monotony；relieve the monotony；the monotony of。','monotonous 是形容词，monotony 是名词；写 the work is monotonous，或 the monotony of the work，不要交换位置。',('A short walk helped break the monotony of the afternoon.','出去走一小会儿，打破了下午的单调。'),('She found ways to relieve the monotony of repetitive work.','她找到了减轻重复工作乏味感的方法。'),sources=['https://www.etymonline.com/word/monotony','https://en.wiktionary.org/wiki/monotony']),
E('monotonic','英 /ˌmɒnəˈtɒnɪk/；美 /ˌmɑːnəˈtɑːnɪk/','单调的〔数学、技术〕；单一音调的','变化沿一个方向走，不忽上忽下折回来。','mono-“单一”与 ton- 音调一族结合，相关形式加 -ic；技术义从单一变化特征发展，需按具体定义理解。',M+[['英语 monotonic','单一调子；数学中变化方向不反转']],'一个序列可以单调不减，例如1、1、3、5；严格递增则不允许相邻值相等。技术里的 monotonic clock 强调时钟读数不会倒退，不等于它显示现实世界的日期，也不保证不同设备的读数可直接对齐。','a monotonic sequence；a monotonic function；a monotonic clock；strictly monotonic。','monotonous 常是生活里的乏味，monotonic 常是中性的数学性质。有些教材对递增等术语约定不同，要看是否允许相等。',('The sequence is monotonic because its values never decrease.','这个序列是单调的，因为它的值从不下降。'),('The program uses a monotonic clock to measure elapsed time.','程序使用单调时钟来测量经过的时间。'),sources=['https://en.wiktionary.org/wiki/monotonic','https://docs.python.org/3/library/time.html#time.monotonic']),
E('overtone','英 /ˈəʊvətəʊn/；美 /ˈoʊvərtoʊn/','泛音；暗含的意味或色彩','主声音旁边还带着别的声音；主话题里也可能带着另一层意味。','over- + tone，音乐义仿译德语 Oberton“上方的音”；后来比喻额外的含义或色彩。',B+[['德语 Oberton → 英语 over- + tone','高于基音的分音'],['英语 overtone 的比喻义','话语或事件附带的暗示与色彩']],'音乐中的 overtone 指高于基音的分音，泛音会影响音色；不必把所有泛音都当成基频的整数倍谐波。a story with political overtones 是故事带政治意味，这些意味可能没有被明说，但读者感受得到。','political overtones；religious overtones；overtones of concern；musical overtones。','overtone 与 undertone 的比喻义有重叠，不是一个必须公开、一个必须隐藏。先看作者要突出附带意味还是潜在情绪。',('The speech had clear political overtones.','这篇演讲带有明显的政治意味。'),('The instrument produces a rich set of overtones.','这件乐器能产生丰富的泛音。'),sources=['https://www.etymonline.com/word/overtone','https://en.wiktionary.org/wiki/overtone']),
E('undertone','英 /ˈʌndətəʊn/；美 /ˈʌndərtoʊn/','低声；潜在意味、暗含情绪；底色','表面声音下面，隐约还有一层情绪或颜色。','under-“下面、较低”+ tone“声音、调子”；低声义与潜在色彩的比喻相互关联。',B+[['英语 under- + tone → undertone','低声；下面隐约带着的调子'],['英语 undertone 的扩展义','潜在情绪、底色']],'speak in an undertone 是低声说话，an undertone of anger 是话听着克制，却隐约带怒意。描述颜色时 a yellow undertone 是偏黄的底色；这里的 under 是较不显眼的一层，不要求有物理上分开的涂层。','in an undertone；an undertone of anger；warm undertones。','undertone 的低声义看音量，monotone 看声音起伏。一个人可以低声说话但语调丰富，也可以很大声却平板单调。',('They spoke in undertones while the lecture continued.','讲座继续时，他们压低声音交谈。'),('There was an undertone of disappointment in his reply.','他的回答里隐约透着失望。'),sources=['https://en.wiktionary.org/wiki/undertone','https://www.etymonline.com/word/undertone'])]
